def resolve(path, cwd, links):
    # Convert path to absolute if relative
    if not path.startswith('/'):
        path = cwd + '/' + path

    # Split into components and filter empty ones
    components = [c for c in path.split('/') if c]

    # Resolve components left to right
    current = ''  # Current canonical absolute path
    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        if component == '.' or component == '':
            # Skip empty and '.'
            i += 1
            continue
        elif component == '..':
            # Move to parent
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue
        else:
            # Append component
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if it's a symlink
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None

                # Get the symlink target
                target = links[candidate]

                # Convert target to absolute if relative
                if not target.startswith('/'):
                    # Relative to the directory containing the link
                    if candidate == '/':
                        target_base = '/'
                    else:
                        target_base = candidate.rsplit('/', 1)[0]
                        if target_base == '':
                            target_base = '/'

                    if target_base == '/':
                        target = '/' + target
                    else:
                        target = target_base + '/' + target

                # Split target into components and prepend to remaining components
                target_components = [c for c in target.split('/') if c]
                remaining = components[i+1:]
                components = target_components + remaining

                # Reset current to empty and continue from start
                current = ''
                i = 0
            else:
                # Regular file/directory, append to current
                current = candidate
                i += 1

    # Handle final result
    if current == '':
        current = '/'

    return current

